import {GUIDE_KEY,GUIDE_STEPS,guideRestore,guideMove,guideStatus} from './recording-guide-core.mjs';
const $=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const page=location.pathname.endsWith('/morning.html')?'morning':'demo';
let dock='top';
const shortActions={ready:'세로 화면 · 방해 금지 · 기기 소리로 5초 테스트. 준비되면 다음을 눌러요.',opening:'첫 문장과 우산 그림을 2~3초 보여주세요.',voice:'English voice 선택 → Listen to a short sample. 음성이 없으면 대본을 보여주세요.',play:'Play morning preview를 누르고 끝까지 들은 뒤 다음으로 가요.',bundle:'What Grandma left for you.의 공지 · 하루 기록 · 그림을 차례로 보여주세요.',open:'Open the morning app →를 누른 뒤 다음으로 가요.',rain:'Rain · 17° · Autumn을 보여주세요. 다르면 Change the weather → Use rainy sample.', 'weather-pack':'Boots for little adventures와 An umbrella to share를 직접 눌러 Checked by you로 바꿔요.', 'source-open':'Check the nursery notice → 또는 하단 Source를 누르세요.', 'source-review':'5개 항목의 원문을 대조하고 I checked this against the source를 각각 체크해요.', 'prepare-open':'Continue to preparation →를 누르세요.',pack:'Colored paper + Glue stick만 체크. Apron은 남겨 2 of 3 packed로 맞춰요.', 'family-open':'See family preview →를 누르세요.',family:'2 PACKED / 1 STILL TO CHECK를 보여준 뒤 Return to a little moment →.', 'moment-open':'비에 관한 질문을 보여주고 Keep this moment를 누르세요.', 'moment-save':'문장을 확인해요. 가상 경험 시연 후 We tried this together 체크 → Save this little moment.', 'moment-card':'Moments의 문장 카드와 Saved on this device를 2~3초 보여주세요.',skin:'오른쪽 위 팔레트 → Moss Green 등 원하는 색 → ×로 닫으세요.',finish:'완료! 실제 연동이 아닌 예시 표시는 남기고, 화면 녹화를 마무리하세요.'};
let state=guideRestore(null),lastFocus=null,marked=null,refreshQueued=false,storageWarning=false;
try{state=guideRestore(JSON.parse(sessionStorage.getItem(GUIDE_KEY)||'null'));}catch{storageWarning=true;}
const requested=new URLSearchParams(location.search).get('guide');
if(requested==='1')state.mode='open';if(requested==='off')state.mode='clean';
const host=document.createElement('div');host.id='recording-guide-root';document.body.append(host);
const launcher=document.createElement('div');launcher.className='recording-guide-footer';launcher.innerHTML='<button type="button" data-guide-action="open">Recording guide</button><span>Optional Korean walkthrough · Hidden during clean recording</span>';document.body.append(launcher);
function store(){try{sessionStorage.setItem(GUIDE_KEY,JSON.stringify(state));storageWarning=false;}catch{storageWarning=true;}}
function snapshot(){return {page,route:location.hash.slice(1)||'today',voiceAvailable:[...($('#voice-choice')?.options||[])].some(o=>o.value&&!/^(No |Checking)/.test(o.textContent)),voicePlaying:!!$('#voice-status')&&/^Playing the fictional briefing/.test($('#voice-status').textContent),reviewed:[...document.querySelectorAll('[data-review]:checked')].map(n=>n.dataset.review),packed:[...document.querySelectorAll('[data-pack]:checked')].map(n=>n.dataset.pack),weatherPacked:[...document.querySelectorAll('[data-action="weather-pack"][aria-pressed="true"]')].map(n=>n.dataset.id),weatherCondition:$('.weather-reading')?.textContent.includes('Rain')?'rain':'other',weatherSource:$('.source-badge')?.textContent.startsWith('Sample weather')?'sample':'other',momentsCount:document.querySelectorAll('.memory-card').length,skin:document.documentElement.dataset.skin,dialogOpen:!!$('#demo-dialog')?.open,momentDialog:!!$('#demo-dialog')?.open&&!!$('#moment-words')};}
function unmark(){marked?.classList.remove('recording-guide-target');marked=null;}
function mark(scroll=false){unmark();if(state.mode==='clean')return;const step=GUIDE_STEPS[state.index];const target=step.target&&$(step.target);if(!target)return;marked=target;target.classList.add('recording-guide-target');if(scroll){state.mode='compact';store();render();target.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
function setMode(mode){state={...state,mode};store();render();if(mode==='clean'){unmark();document.querySelectorAll('.recording-guide-dialog-tip').forEach(n=>n.remove());lastFocus?.focus?.({preventScroll:true});}else if(mode==='open')$('#recording-guide-heading')?.focus({preventScroll:true});}
function routeMismatch(step,s,status){return !status.done&&(step.page!==s.page||(step.route&&step.route!==s.route));}
function render(){const step=GUIDE_STEPS[state.index],s=snapshot(),status=guideStatus(step,s);const mismatch=routeMismatch(step,s,status);unmark();document.documentElement.dataset.recordingGuide=state.mode;
 if(state.mode==='clean'){host.innerHTML='';syncDialog();return;}
 if(state.mode==='compact'){host.innerHTML=`<aside class="recording-guide-strip" data-dock="${dock}" lang="ko" aria-label="녹화 중 짧은 안내"><div><b>${state.index+1}/${GUIDE_STEPS.length} · ${esc(step.title)}</b><button type="button" data-guide-action="move" aria-label="안내 위치 바꾸기">${dock==='top'?'아래로':'위로'}</button><button type="button" data-guide-action="clean" aria-label="안내 숨기기">×</button></div><p>${esc(shortActions[step.id]||step.body[0])}</p><nav aria-label="안내 조작"><button type="button" data-guide-action="prev" ${state.index===0?'disabled':''}>이전</button><button type="button" data-guide-action="open">자세히</button><button type="button" data-guide-action="${mismatch?'route':'locate'}">${mismatch?'화면 열기':'위치 보기'}</button><button type="button" data-guide-action="next" ${state.index===GUIDE_STEPS.length-1?'disabled':''}>다음 →</button></nav></aside>`;mark();syncDialog();return;}
 host.innerHTML=`<aside class="recording-guide-panel" lang="ko" aria-labelledby="recording-guide-heading"><div class="recording-guide-top"><span>녹화 연습 안내 · 앱과 별도</span><button type="button" data-guide-action="compact" aria-label="안내 작게 보기">작게 보기</button><button type="button" data-guide-action="clean">화면만 보기</button></div><div class="recording-guide-body"><label class="recording-guide-picker">장면 선택<select id="recording-guide-step" aria-label="튜토리얼 장면 선택">${GUIDE_STEPS.map((x,i)=>`<option value="${i}" ${i===state.index?'selected':''}>${i+1}. ${esc(x.title)}</option>`).join('')}</select></label><h2 id="recording-guide-heading" tabindex="-1">${esc(step.title)}</h2><ol>${step.body.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="recording-guide-shot"><b>촬영 팁</b> ${esc(step.shot)}</p>${step.note?`<p class="recording-guide-note">${esc(step.note)}</p>`:''}<p class="recording-guide-status" role="status" data-done="${status.done}">${status.done?'✓ ':''}${esc(status.text)}</p>${mismatch?'<p class="recording-guide-note">지금은 다른 화면에 있어요. 아래 버튼은 화면만 이동하고 체크나 저장은 하지 않아요.</p>':''}${storageWarning?'<p class="recording-guide-note">이 브라우저에서는 안내 진행 상태를 저장할 수 없어요. 이동한 뒤 장면 선택으로 이어가 주세요.</p>':''}</div><div class="recording-guide-actions">${mismatch?'<button type="button" data-guide-action="route">이 단계 화면 열기</button>':step.target?'<button type="button" data-guide-action="locate">작게 보고 버튼 위치 찾기</button>':''}<div><button type="button" data-guide-action="prev" ${state.index===0?'disabled':''}>이전</button><button type="button" data-guide-action="next" ${state.index===GUIDE_STEPS.length-1?'disabled':''}>다음 단계</button></div><button type="button" class="recording-guide-restart" data-guide-action="restart">처음부터 연습 · 앱 기록 유지</button></div></aside>`;mark();syncDialog();}
function syncDialog(){const d=$('#demo-dialog');if(!d?.open||state.mode==='clean'){document.querySelectorAll('.recording-guide-dialog-tip').forEach(n=>n.remove());host.style.visibility='';return;}host.style.visibility='hidden';const step=GUIDE_STEPS[state.index];let tip=d.querySelector('.recording-guide-dialog-tip');if(!tip){tip=document.createElement('aside');tip.className='recording-guide-dialog-tip';tip.lang='ko';d.insertBefore(tip,d.firstChild);}let title=step.title,body=step.body.join(' ');if($('#moment-words')){title='문장을 확인하고, 경험 후에만 저장';body='Suggested words를 읽거나 수정해 주세요. 가상 상황을 직접 시연했다면 We tried this together를 체크한 뒤 Save this little moment를 눌러요. 하지 않았다면 Cancel로 닫아도 됩니다. 저장은 이 기기에만 남아요.';}else if($('#weather-condition')){title='비 오는 예시로 돌아가기';body='Use rainy sample을 누르면 17°C 가을비 예시로 돌아와요. 실제 날씨는 아니고, 기존 날씨 준비 체크는 초기화돼요. 앱의 원문 확인과 포장 체크는 그대로예요.';}else if(d.querySelector('[data-action="skin"]')){title='원하는 색을 고르고 ×로 닫아요';body='Moss Green 등 원하는 색을 누르면 바로 적용돼요. × 또는 Cancel은 창을 닫기만 하며 이미 선택한 색은 유지됩니다.';}else if(d.querySelector('[data-action="reset-confirm"]')){title='기록을 지우기 전, 한 번 더 확인';body='Reset English demo를 누르면 영어 데모의 체크, 색, 날씨와 저장 카드가 지워져요. 원하지 않으면 Cancel을 누르세요. 안내를 다시 시작하는 데 초기화는 필요하지 않아요.';}
 const html=`<b>${esc(title)}</b><p>${esc(body)}</p><button type="button" data-guide-action="clean">안내 숨기고 화면만 보기</button><button type="button" data-guide-action="modal-next">다음 안내 단계</button>`;if(tip.innerHTML!==html)tip.innerHTML=html;
}
function refresh(){if(refreshQueued)return;refreshQueued=true;queueMicrotask(()=>{refreshQueued=false;render();});}
function go(delta){state=guideMove(state,delta);if(state.mode==='clean')state.mode='open';store();render();$('#recording-guide-heading')?.focus({preventScroll:true});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-guide-action]');if(!b)return;const a=b.dataset.guideAction;if(a==='open'){lastFocus=b;setMode('open');}else if(a==='clean'||a==='compact')setMode(a);else if(a==='move'){dock=dock==='top'?'bottom':'top';render();}else if(a==='next'||a==='modal-next')go(1);else if(a==='prev')go(-1);else if(a==='locate')mark(true);else if(a==='restart'){state={version:1,index:0,mode:'open'};store();render();}else if(a==='route'){const step=GUIDE_STEPS[state.index];store();if(step.page!==page)location.href=`./${step.page==='morning'?'morning':'demo'}.html${step.route?'#'+step.route:''}`;else if(step.route)location.hash=step.route;else window.scrollTo({top:0,behavior:'smooth'});}});
document.addEventListener('change',e=>{if(e.target.id==='recording-guide-step'){const i=Number(e.target.value);if(Number.isInteger(i)&&i>=0&&i<GUIDE_STEPS.length){state.index=i;store();render();}}else refresh();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.mode==='open'&&!$('#demo-dialog')?.open){setMode('compact');}});
const observe=new MutationObserver(refresh);for(const node of [$('#demo-app'),$('#morning-app')])if(node)observe.observe(node,{childList:true,subtree:true,characterData:true});if($('#demo-dialog'))observe.observe($('#demo-dialog'),{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
window.addEventListener('hashchange',()=>{render();});window.addEventListener('popstate',()=>{render();});
store();render();
